/**
 * Saul's First Victory
 * --------------------
 * Nahash the Ammonite threatens Jabesh-gilead, and Saul cuts his oxen and sends the pieces through Israel; the people rally and win. Stage: a field of oxen at noon, a yoke of oxen cut in pieces, a trumpet being blown, the people coming up from the fields; a first victory.
 *
 * Palette 0x1a2a1a → 0x060402 · light: dusk · hero: horn
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./samuel-kit.js.
 */

import { THREE, createScene, oak, tree, wheat, horn, person, crowd, birds } from './samuel-kit.js';

const BG = 0x1a2a1a;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3448236675, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* trees: broadleaf shade */
    oak(W, group, 12.7, 0, 4.5, 1.08, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -54.6, 0, 2.8, 0.91, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -13.3, 0, -15.9, 0.94, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -60.7, 0, -43.4, 1.14, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    tree(W, group, -16.3, 0, 5.0, 1.1);

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x1d2e1d, head: 0x213521 });

    /* hero: the horn */
    horn(W, group, 0, 1.2, 0, 1.3, { color: 0x172617 });
    W.disc([0, 4, -10], 4, 0x223722, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.58, s: 1.17 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 14, 70, 44, [0x1a2a1a, 0x060402, 0x8a6a44, 0x6a4a30, 0xc8b088, 0x5a4a6a]);

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
